arguments.command:
cd /workspace/results/run100; python3 - <<'EOF'
import json, collections
c=collections.Counter()
for line in open('val_generations/100.jsonl'):
    d=json.loads(line)
    if '\\boxed' not in d['output']:
        c[d['output'][-120:][:60]]+=1
print(len(c))
for k,v in c.most_common(3): print(v, repr(k))
# sample an unboxed output
for line in open('val_generations/100.jsonl'):
    d=json.loads(line)
    if '\\boxed' not in d['output']:
        print(repr(d['output'][:400])); break
EOF

